-- hivemind's verdict per node: `category` is the thread ROOT's community, propagated
-- to every descendant. Our derivation must reproduce it from parent links alone.
-- haf_stats_test is created by the regression harness on a real node, but the stub
-- stack does not load that, so create it here too.
CREATE SCHEMA IF NOT EXISTS haf_stats_test;

CREATE TABLE IF NOT EXISTS haf_stats_test.mainnet_community_expected (
    author TEXT NOT NULL,
    permlink TEXT NOT NULL,
    depth INT NOT NULL,
    hivemind_category TEXT NOT NULL,
    expected_community TEXT,
    PRIMARY KEY (author, permlink)
);

