-- One batch spanning the whole sample, so most parent links are resolved IN-BATCH -
-- the case a plain comment_registry lookup gets wrong.
SELECT haf_stats_app.process_community_registry(37502401, 37502528);
SELECT haf_stats_app.process_content_stats(37502401, 37502528);

DO $$
DECLARE
    _total INT;
    _wrong INT;
    _worst TEXT;
    _deep INT;
BEGIN
    SELECT COUNT(*) INTO _total FROM haf_stats_test.mainnet_community_expected;

    SELECT COUNT(*), MAX(e.depth) INTO _wrong, _deep
    FROM haf_stats_test.mainnet_community_expected e
    JOIN hafd.accounts a ON a.name = e.author
    JOIN haf_stats_backend.comment_registry r
        ON r.author_id = a.id AND r.permlink = e.permlink
    WHERE r.community IS DISTINCT FROM e.expected_community;

    IF _wrong <> 0 THEN
        SELECT FORMAT('%s/%s depth=%s ours=%s hivemind=%s',
                      e.author, e.permlink, e.depth,
                      COALESCE(r.community, '(none)'), e.hivemind_category)
        INTO _worst
        FROM haf_stats_test.mainnet_community_expected e
        JOIN hafd.accounts a ON a.name = e.author
        JOIN haf_stats_backend.comment_registry r
            ON r.author_id = a.id AND r.permlink = e.permlink
        WHERE r.community IS DISTINCT FROM e.expected_community
        ORDER BY e.depth DESC
        LIMIT 1;

        RAISE EXCEPTION 'mainnet community parity: % of % real nodes resolved to a different community than hivemind reports (deepest disagreement: %)',
            _wrong, _total, _worst;
    END IF;

    -- Guard the test itself: if the sample stopped containing deep replies or
    -- community content, it would pass while proving nothing.
    SELECT MAX(depth) INTO _deep FROM haf_stats_test.mainnet_community_expected;
    IF _deep < 3 THEN
        RAISE EXCEPTION 'mainnet community fixture is too shallow (max depth %); regenerate it - it is no longer testing multi-level root resolution', _deep;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM haf_stats_test.mainnet_community_expected WHERE expected_community IS NOT NULL)
       OR NOT EXISTS (SELECT 1 FROM haf_stats_test.mainnet_community_expected WHERE expected_community IS NULL) THEN
        RAISE EXCEPTION 'mainnet community fixture lost either its community or its legacy-category nodes; regenerate it';
    END IF;

    RAISE NOTICE 'mainnet community parity OK: % real nodes (max depth %) resolved exactly as hivemind reports them.', _total, _deep;
END;
$$;

